css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); display: grid; place-items: center; perspective: 500px; }
.loader span { width: 80%; height: 80%; border-radius: 50%; background: conic-gradient(from 0deg, var(--accent), var(--accent-2), var(--accent)); -webkit-mask: radial-gradient(transparent 56%, #000 58%); mask: radial-gradient(transparent 56%, #000 58%); animation: torus calc(var(--loader-speed) * 2.4) linear infinite; }
@keyframes torus { 0% { transform: rotateX(66deg) rotate(0deg); } 100% { transform: rotateX(66deg) rotate(360deg); } }
